export class ScheduleComponent {
  constructor() {
    // =========================================================
    // Schedule Data
    // =========================================================
    this.schedules = [{
      className: 'Mathematics',
      classNumber: 'Class 01',
      subject: 'Mathematics',
      teacher: 'Ahmed Hassan',
      group: 'Group A',
      day: 'Saturday',
