d[_ngcontent-%COMP%]   h3[_ngcontent-%COMP%] {\n  margin: 0 0 22px;\n\n  color: var(--text-color);\n\n  font-size: 20px;\n}\n\n\n\n\n\n\n\n.form-group[_ngcontent-%COMP%] {\n  margin-bottom: 16px;\n}\n\n.form-group[_ngcontent-%COMP%]   label[_ngcontent-%COMP%] {\n  display: block;\n\n  margin-bottom: 7px;\n\n  color: var(--text-color);\n\n  font-size: 13px;\n}\n\n.form-group[_ngcontent-%COMP%]   input[_ngcontent-%COMP%], .form-group[_ngcontent-%COMP%]   select[_ngcontent-%COMP%] {\n  width: 100%;\n\n  box-sizing: border-box;\n\n  padding: 11px 12px;\n\n  font-size: 14px;\n\n  color: var(--text-color);\n\n  background: var(--white);\n\n  border: 1px solid var(--border-color);\n\n  border-radius: var(--radius-small);\n\n  outline: none;\n}\n\n.form-group[_ngcontent-%COMP%]   input[_ngcontent-%COMP%]:focus, .form-group[_ngcontent-%COMP%]   select[_ngcontent-%COMP%]:focus {\n  border-color: var(--primary-color);\n}\n\n\n\n\n\n\n\n.modal-actions[_ngcontent-%COMP%] {\n  display: flex;\n\n  justify-content: flex-end;\n\n  gap: 10px;\n\n  margin-top: 25px;\n}\n\n.btn--ghost-dark[_ngcontent-%COMP%] {\n  padding: 10px 16px;\n\n  background: #f1f5f9;\n\n  color: #475569;\n\n  border-radius: var(--radius-small);\n}\n\n.btn--ghost-dark[_ngcontent-%COMP%]:hover {\n  background: #e2e8f0;\n}\n\n\n\n\n\n\n\n.schedule-details[_ngcontent-%COMP%] {\n  display: flex;\n\n  flex-direction: column;\n\n  gap: 13px;\n\n  margin: 20px 0;\n\n  color: #475569;\n\n  font-size: 14px;\n}\n\n.schedule-details[_ngcontent-%COMP%]   strong[_ngcontent-%COMP%] {\n  color: var(--text-color);\n}\n\n\n\n\n\n\n\n@media (max-width: 1200px) {\n\n  .schedule-card__header[_ngcontent-%COMP%] {\n    align-items: flex-start;\n\n    flex-direction: column;\n  }\n\n  .schedule-filters[_ngcontent-%COMP%] {\n    width: 100%;\n  }\n\n}\n\n\n@media (max-width: 1150px) {\n\n  .stats-grid[_ngcontent-%COMP%] {\n    grid-template-columns: repeat(2, 1fr);\n  }\n\n}\n\n\n@media (max-width: 750px) {\n\n  .schedule-page[_ngconte