import { Component, OnInit } from '@angular/core';

interface Schedule {
  className: string;
  classNumber: string;
  subject: string;
  teacher: string;
  group: string;
  day: string;
  time: string;
  room: string;
  icon: string;
}

@Component({
  selector: 'app-schedule',
  templateUrl: './schedule.component.html',
  styleUrls: ['./schedule.component.css']
})
export class ScheduleComponent implements OnInit {

  // =========================================================
  // Schedule Data
  // =========================================================

  schedules: Schedule[] = [
    {
      className: 'Mathematics',
      classNumber: 'Class 01',
      subject: 'Mathematics',
      teacher: 'Ahmed Hassan',
      group: 'Group A',
      day: 'Saturday',
      time: '09:00 AM',
      room: 'Room 101',
      icon: 'fa-book'
    },
    {
      className: 'English',
      classNumber: 'Class 02',
      subject: 'English',
      teacher: 'Mohamed Ali',
      group: 'Group B',
      day: 'Sunday',
      time: '11:00 AM',
      room: 'Room 202',
      icon: 'fa-language'
    },
    {
      className: 'Physics',
      classNumber: 'Class 03',
      subject: 'Physics',
      teacher: 'Youssef Ahmed',
      group: 'Group A',
      day: 'Monday',
      time: '01:00 PM',
      room: 'Room 103',
      icon: 'fa-atom'
    },
    {
      className: 'Chemistry',
      classNumber: 'Class 04',
      subject: 'Chemistry',
      teacher: 'Ahmed Hassan',
      group: 'Group C',
      day: 'Tuesday',
      time: '10:00 AM',
      room: 'Room 105',
      icon: 'fa-flask'
    },
    {
      className: 'Arabic',
      classNumber: 'Class 05',
      subject: 'Arabic',
      teacher: 'Mohamed Ali',
      group: 'Group B',
      day: 'Wednesday',
      time: '02:00 PM',
      room: 'Room 201',
      icon: 'fa-book-open'
    }
  ];

  filteredSchedules: Schedule[] = [];

  // =========================================================
  // Filter Options
  // =========================================================

  days: string[] = [
    'Saturday',
    'Sunday',
    'Monday',
    'Tuesday',
    'Wednesday',
    'Thursday'
  ];

  groups: string[] = [];
  teachers: string[] = [];

  searchValue: string = '';
  selectedDay: string = '';
  selectedGroup: string = '';
  selectedTeacher: string = '';

  // =========================================================
  // Modals
  // =========================================================

  isModalOpen: boolean = false;
  isDetailsModalOpen: boolean = false;

  selectedSchedule: Schedule | null = null;

  // =========================================================
  // Add / Edit Schedule
  // =========================================================

  newSchedule = {
    className: '',
    classNumber: '',
    subject: '',
    teacher: '',
    group: '',
    day: '',
    time: '',
    room: '',
    icon: 'fa-calendar-days'
  };

  isEditMode: boolean = false;

  // =========================================================
  // Lifecycle
  // =========================================================

  ngOnInit(): void {
    this.updateFilterOptions();
    this.filteredSchedules = [...this.schedules];
  }

  // =========================================================
  // Statistics
  // =========================================================

  get todaysClassesCount(): number {

    const todayIndex = new Date().getDay();

    const dayNames = [
      'Sunday',
      'Monday',
      'Tuesday',
      'Wednesday',
      'Thursday',
      'Friday',
      'Saturday'
    ];

    const today = dayNames[todayIndex];

    return this.schedules.filter(
      schedule => schedule.day === today
    ).length;
  }

  get teachersCount(): number {

    return new Set(
      this.schedules
        .map(schedule => schedule.teacher)
        .filter(teacher => teacher.trim())
    ).size;
  }

  get groupsCount(): number {

    return new Set(
      this.schedules
        .map(schedule => schedule.group)
        .filter(group => group.trim())
    ).size;
  }

  // =========================================================
  // Initials
  // =========================================================

  getInitials(name: string): string {

    return name
      .split(' ')
      .filter(word => word.length > 0)
      .map(word => word.charAt(0))
      .join('')
      .substring(0, 2)
      .toUpperCase();
  }

  // =========================================================
  // Filter Options
  // =========================================================

  updateFilterOptions(): void {

    this.groups = [
      ...new Set(
        this.schedules
          .map(schedule => schedule.group)
          .filter(group => group.trim())
      )
    ];

    this.teachers = [
      ...new Set(
        this.schedules
          .map(schedule => schedule.teacher)
          .filter(teacher => teacher.trim())
      )
    ];
  }

  // =========================================================
  // Filters
  // =========================================================

  applyFilters(): void {

    const search = this.searchValue
      .toLowerCase()
      .trim();

    this.filteredSchedules =
      this.schedules.filter(schedule => {

        const matchesSearch =
          !search ||
          schedule.className.toLowerCase().includes(search) ||
          schedule.subject.toLowerCase().includes(search) ||
          schedule.teacher.toLowerCase().includes(search) ||
          schedule.group.toLowerCase().includes(search) ||
          schedule.room.toLowerCase().includes(search);

        const matchesDay =
          !this.selectedDay ||
          schedule.day === this.selectedDay;

        const matchesGroup =
          !this.selectedGroup ||
          schedule.group === this.selectedGroup;

        const matchesTeacher =
          !this.selectedTeacher ||
          schedule.teacher === this.selectedTeacher;

        return (
          matchesSearch &&
          matchesDay &&
          matchesGroup &&
          matchesTeacher
        );
      });
  }

  // =========================================================
  // Add Schedule
  // =========================================================

  onAddScheduleClick(): void {

    this.isEditMode = false;

    this.selectedSchedule = null;

    this.newSchedule = {
      className: '',
      classNumber: '',
      subject: '',
      teacher: '',
      group: '',
      day: '',
      time: '',
      room: '',
      icon: 'fa-calendar-days'
    };

    this.isModalOpen = true;
  }

  // =========================================================
  // Close Modal
  // =========================================================

  closeModal(): void {

    this.isModalOpen = false;

    this.selectedSchedule = null;

    this.isEditMode = false;
  }

  // =========================================================
  // Save / Update Schedule
  // =========================================================

  saveSchedule(): void {

    if (
      !this.newSchedule.className.trim() ||
      !this.newSchedule.subject.trim() ||
      !this.newSchedule.teacher.trim() ||
      !this.newSchedule.group.trim() ||
      !this.newSchedule.day ||
      !this.newSchedule.time.trim() ||
      !this.newSchedule.room.trim()
    ) {
      return;
    }

    // =======================================================
    // Edit Existing Schedule
    // =======================================================

    if (this.isEditMode && this.selectedSchedule) {

      this.selectedSchedule.className =
        this.newSchedule.className.trim();

      this.selectedSchedule.subject =
        this.newSchedule.subject.trim();

      this.selectedSchedule.teacher =
        this.newSchedule.teacher.trim();

      this.selectedSchedule.group =
        this.newSchedule.group.trim();

      this.selectedSchedule.day =
        this.newSchedule.day;

      this.selectedSchedule.time =
        this.newSchedule.time.trim();

      this.selectedSchedule.room =
        this.newSchedule.room.trim();

    }

    // =======================================================
    // Add New Schedule
    // =======================================================

    else {

      const schedule: Schedule = {

        className:
          this.newSchedule.className.trim(),

        classNumber:
          this.newSchedule.classNumber.trim() ||
          `Class ${String(this.schedules.length + 1).padStart(2, '0')}`,

        subject:
          this.newSchedule.subject.trim(),

        teacher:
          this.newSchedule.teacher.trim(),

        group:
          this.newSchedule.group.trim(),

        day:
          this.newSchedule.day,

        time:
          this.newSchedule.time.trim(),

        room:
          this.newSchedule.room.trim(),

        icon:
          this.newSchedule.icon
      };

      this.schedules.push(schedule);
    }

    this.updateFilterOptions();

    this.applyFilters();

    this.closeModal();
  }

  // =========================================================
  // View Schedule
  // =========================================================

  viewSchedule(schedule: Schedule): void {

    this.selectedSchedule = schedule;

    this.isDetailsModalOpen = true;
  }

  // =========================================================
  // Close Details Modal
  // =========================================================

  closeDetailsModal(): void {

    this.isDetailsModalOpen = false;

    this.selectedSchedule = null;
  }

  // =========================================================
  // Edit Schedule
  // =========================================================

  editSchedule(schedule: Schedule): void {

    this.selectedSchedule = schedule;

    this.isEditMode = true;

    this.newSchedule = {

      className:
        schedule.className,

      classNumber:
        schedule.classNumber,

      subject:
        schedule.subject,

      teacher:
        schedule.teacher,

      group:
        schedule.group,

      day:
        schedule.day,

      time:
        schedule.time,

      room:
        schedule.room,

      icon:
        schedule.icon
    };

    this.isModalOpen = true;
  }

  // =========================================================
  // Delete Schedule
  // =========================================================

  deleteSchedule(schedule: Schedule): void {

    const index =
      this.schedules.indexOf(schedule);

    if (index !== -1) {

      this.schedules.splice(index, 1);

      this.updateFilterOptions();

      this.applyFilters();
    }
  }
}
<section class="schedule-page">

  <!-- ==================== Header ==================== -->
  <div class="schedule-header-banner">
    <div class="schedule-page__header">

      <div>
        <h2 class="schedule-page__title">Schedule</h2>

        <p class="schedule-page__subtitle">
          Manage classes, lessons, and schedules.
        </p>
      </div>

      <div class="schedule-page__actions">
        <button
          type="button"
          class="btn btn--primary"
          (click)="onAddScheduleClick()"
        >
          <svg
            width="16"
            height="16"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
          >
            <path
              d="M12 5v14M5 12h14"
              stroke-linecap="round"
            ></path>
          </svg>

          Add Schedule
        </button>
      </div>

    </div>
  </div>


  <!-- ==================== Statistics ==================== -->
  <div class="stats-grid">

    <!-- Total Classes -->
    <div class="stat-card">

      <div class="stat-icon stat-icon--blue">
        <i class="fa-solid fa-calendar-days"></i>
      </div>

      <div class="stat-content">
        <span class="stat-title">Total Classes</span>
        <strong>{{ schedules.length }}</strong>
        <span class="stat-description">
          All scheduled classes
        </span>
      </div>

    </div>


    <!-- Today's Classes -->
    <div class="stat-card">

      <div class="stat-icon stat-icon--green">
        <i class="fa-solid fa-calendar-check"></i>
      </div>

      <div class="stat-content">
        <span class="stat-title">Today's Classes</span>
        <strong>{{ todaysClassesCount }}</strong>
        <span class="stat-description">
          Classes today
        </span>
      </div>

    </div>


    <!-- Teachers -->
    <div class="stat-card">

      <div class="stat-icon stat-icon--orange">
        <i class="fa-solid fa-chalkboard-user"></i>
      </div>

      <div class="stat-content">
        <span class="stat-title">Teachers</span>
        <strong>{{ teachersCount }}</strong>
        <span class="stat-description">
          Active teachers
        </span>
      </div>

    </div>


    <!-- Groups -->
    <div class="stat-card">

      <div class="stat-icon stat-icon--purple">
        <i class="fa-solid fa-users"></i>
      </div>

      <div class="stat-content">
        <span class="stat-title">Groups</span>
        <strong>{{ groupsCount }}</strong>
        <span class="stat-description">
          Active groups
        </span>
      </div>

    </div>

  </div>


  <!-- ==================== Schedule List ==================== -->
  <div class="schedule-card">

    <!-- Card Header -->
    <div class="schedule-card__header">

      <div>
        <h3>Schedule List</h3>

        <p>
          {{ filteredSchedules.length }} classes found
        </p>
      </div>


      <!-- Filters -->
      <div class="schedule-filters">

        <!-- Day Filter -->
        <select
          [(ngModel)]="selectedDay"
          (change)="applyFilters()"
        >
          <option value="">All Days</option>

          <option
            *ngFor="let day of days"
            [value]="day"
          >
            {{ day }}
          </option>
        </select>


        <!-- Group Filter -->
        <select
          [(ngModel)]="selectedGroup"
          (change)="applyFilters()"
        >
          <option value="">All Groups</option>

          <option
            *ngFor="let group of groups"
            [value]="group"
          >
            {{ group }}
          </option>
        </select>


        <!-- Teacher Filter -->
        <select
          [(ngModel)]="selectedTeacher"
          (change)="applyFilters()"
        >
          <option value="">All Teachers</option>

          <option
            *ngFor="let teacher of teachers"
            [value]="teacher"
          >
            {{ teacher }}
          </option>
        </select>


        <!-- Search -->
        <div class="search-box">

          <svg
            width="16"
            height="16"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
          >
            <circle
              cx="11"
              cy="11"
              r="8"
            ></circle>

            <path
              d="m21 21-4.3-4.3"
            ></path>
          </svg>

          <input
            type="text"
            placeholder="Search schedules..."
            [(ngModel)]="searchValue"
            (input)="applyFilters()"
          />

        </div>

      </div>

    </div>


    <!-- ==================== Schedule Table ==================== -->
    <div class="table-wrapper">

      <table class="schedule-table">

        <thead>
          <tr>
            <th>CLASS</th>
            <th>SUBJECT</th>
            <th>TEACHER</th>
            <th>GROUP</th>
            <th>DAY</th>
            <th>TIME</th>
            <th>ROOM</th>
            <th>ACTIONS</th>
          </tr>
        </thead>


        <tbody>

          <!-- Schedule Rows -->
          <tr
            *ngFor="let schedule of filteredSchedules"
          >

            <!-- Class -->
            <td>

              <div class="class-cell">

                <div class="class-avatar">
                  <i
                    class="fa-solid"
                    [ngClass]="schedule.icon"
                  ></i>
                </div>

                <div class="class-info">

                  <strong>
                    {{ schedule.className }}
                  </strong>

                  <span>
                    {{ schedule.classNumber }}
                  </span>

                </div>

              </div>

            </td>


            <!-- Subject -->
            <td>
              <span class="text-muted">
                {{ schedule.subject }}
              </span>
            </td>


            <!-- Teacher -->
            <td>
              <div class="teacher-cell">

                <div class="teacher-avatar">
                  {{ getInitials(schedule.teacher) }}
                </div>

                <span>
                  {{ schedule.teacher }}
                </span>

              </div>
            </td>


            <!-- Group -->
            <td>
              <span class="group-badge">
                {{ schedule.group }}
              </span>
            </td>


            <!-- Day -->
            <td>
              {{ schedule.day }}
            </td>


            <!-- Time -->
            <td>
              <span class="time-badge">
                {{ schedule.time }}
              </span>
            </td>


            <!-- Room -->
            <td>
              {{ schedule.room }}
            </td>


            <!-- Actions -->
            <td>

              <div class="actions">

                <!-- View -->
                <button
                  type="button"
                  title="View"
                  (click)="viewSchedule(schedule)"
                >
                  <i class="fa-regular fa-eye"></i>
                </button>


                <!-- Edit -->
                <button
                  type="button"
                  title="Edit"
                  (click)="editSchedule(schedule)"
                >
                  <i class="fa-solid fa-pen"></i>
                </button>


                <!-- Delete -->
                <button
                  type="button"
                  title="Delete"
                  (click)="deleteSchedule(schedule)"
                >
                  <i class="fa-regular fa-trash-can"></i>
                </button>

              </div>

            </td>

          </tr>


          <!-- ==================== Empty State ==================== -->
          <tr *ngIf="filteredSchedules.length === 0">

            <td
              colspan="8"
              class="empty-state"
            >

              <div class="empty-state__icon">
                <i class="fa-solid fa-calendar-days"></i>
              </div>

              <strong>No schedules found</strong>

              <span>
                Try changing your search or filters.
              </span>

            </td>

          </tr>

        </tbody>

      </table>

    </div>

  </div>

</section>


<!-- ========================================================= -->
<!-- Add / Edit Schedule Modal -->
<!-- ========================================================= -->

<div
  class="modal-overlay"
  *ngIf="isModalOpen"
>

  <div class="modal-card">

    <h3>
      {{ isEditMode ? 'Edit Schedule' : 'New Schedule' }}
    </h3>


    <!-- Class Name -->
    <div class="form-group">

      <label>Class Name</label>

      <input
        type="text"
        [(ngModel)]="newSchedule.className"
        placeholder="Enter class name"
      />

    </div>


    <!-- Subject -->
    <div class="form-group">

      <label>Subject</label>

      <input
        type="text"
        [(ngModel)]="newSchedule.subject"
        placeholder="Enter subject"
      />

    </div>


    <!-- Teacher -->
    <div class="form-group">

      <label>Teacher</label>

      <input
        type="text"
        [(ngModel)]="newSchedule.teacher"
        placeholder="Enter teacher name"
      />

    </div>


    <!-- Group -->
    <div class="form-group">

      <label>Group</label>

      <input
        type="text"
        [(ngModel)]="newSchedule.group"
        placeholder="Enter group"
      />

    </div>


    <!-- Day -->
    <div class="form-group">

      <label>Day</label>

      <select [(ngModel)]="newSchedule.day">

        <option value="">
          Select day
        </option>

        <option
          *ngFor="let day of days"
          [value]="day"
        >
          {{ day }}
        </option>

      </select>

    </div>


    <!-- Time -->
    <div class="form-group">

      <label>Time</label>

      <input
        type="text"
        [(ngModel)]="newSchedule.time"
        placeholder="e.g. 09:00 AM"
      />

    </div>


    <!-- Room -->
    <div class="form-group">

      <label>Room</label>

      <input
        type="text"
        [(ngModel)]="newSchedule.room"
        placeholder="Enter room"
      />

    </div>


    <!-- Modal Actions -->
    <div class="modal-actions">

      <button
        type="button"
        class="btn btn--ghost-dark"
        (click)="closeModal()"
      >
        Cancel
      </button>

      <button
        type="button"
        class="btn btn--primary modal-save-btn"
        (click)="saveSchedule()"
      >
        {{ isEditMode ? 'Update Schedule' : 'Save Schedule' }}
      </button>

    </div>

  </div>

</div>


<!-- ========================================================= -->
<!-- Schedule Details Modal -->
<!-- ========================================================= -->

<div
  class="modal-overlay"
  *ngIf="isDetailsModalOpen && selectedSchedule"
>

  <div class="modal-card">

    <h3>Schedule Details</h3>


    <div class="schedule-details">

      <div>
        <strong>Class:</strong>
        {{ selectedSchedule.className }}
      </div>

      <div>
        <strong>Subject:</strong>
        {{ selectedSchedule.subject }}
      </div>

      <div>
        <strong>Teacher:</strong>
        {{ selectedSchedule.teacher }}
      </div>

      <div>
        <strong>Group:</strong>
        {{ selectedSchedule.group }}
      </div>

      <div>
        <strong>Day:</strong>
        {{ selectedSchedule.day }}
      </div>

      <div>
        <strong>Time:</strong>
        {{ selectedSchedule.time }}
      </div>

      <div>
        <strong>Room:</strong>
        {{ selectedSchedule.room }}
      </div>

    </div>


    <div class="modal-actions">

      <button
        type="button"
        class="btn btn--primary modal-save-btn"
        (click)="closeDetailsModal()"
      >
        Close
      </button>

    </div>

  </div>

</div>
